"""Plain text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed

def _check_owner(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark for {mark.student_id} given with {student.student_id}")

def _long_date(day) -> str:
    return f"{day:%B} {day.day}, {day.year}"

def _count_phrase(count: int) -> str:
    return "1 day" if count == 1 else f"{count} days"

# ---
def build_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Write a short notice naming the student, days missed and the dates."""
    marks = list(marks)
    _check_owner(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError(f"no absences for {student.student_id}")
    dates = "; ".join(_long_date(day) for day in days)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {_count_phrase(len(days))}: {dates}."
